// /frontend-react/src/components/Dashboard.js

import React from 'react';

const Icon = ({ name, emoji, isActive, onClick, isEasyMode }) => (
    <div 
        onClick={isActive ? onClick : () => isEasyMode && console.log(`Audio: '${name} - Not Available Yet'`)}
        style={{
            padding: '25px', // More padding
            margin: '15px',
            border: `5px solid ${isActive ? '#007bff' : 'lightgray'}`,
            borderRadius: '15px', // Rounded corners
            width: '40%',
            textAlign: 'center',
            // Highlighting based on activity/easy mode
            backgroundColor: isActive ? '#e3f2fd' : 'white',
            filter: isActive ? 'none' : 'grayscale(100%)', // Grayscale for inactive
            opacity: isActive ? 1 : 0.6, // Faded for inactive
            cursor: isActive ? 'pointer' : 'default',
            boxShadow: isActive ? '0 6px 12px rgba(0,0,100,0.2)' : 'none',
            transition: 'all 0.2s', // Smooth visual transition
            fontSize: isEasyMode ? '36px' : '20px',
        }}
    >
        <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '80px' : '40px'}}>{emoji}</span>
        <p style={{fontWeight: 'bold', color: '#333'}}>{name}</p>
    </div>
);

function Dashboard({ isEasyMode, goToMedical }) {
    return (
        <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', paddingTop: '40px' }}>
            <Icon
                name="Medical Access"
                emoji="🏥"
                isActive={true} 
                onClick={goToMedical}
                isEasyMode={isEasyMode}
            />
            <Icon
                name="Shopping"
                emoji="🛒"
                isActive={false}
                isEasyMode={isEasyMode}
            />
            <Icon
                name="Community"
                emoji="🧑‍🤝‍🧑"
                isActive={false}
                isEasyMode={isEasyMode}
            />
            <Icon
                name="Home Tasks"
                emoji="🏡"
                isActive={false}
                isEasyMode={isEasyMode}
            />
        </div>
    );
}

export default Dashboard;
